/**
 * Charges coming up in the next `within` days (a charge today counts), soonest first.
 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
 * @param {string} today 'YYYY-MM-DD'
 * @param {number} [within=30]
 * @returns {Array<{ name: string, date: string, when: string, inDays: number, price: number, cycle: string }>}
 */
export function upcoming(subs, today, within = 30) {
  const rows = [];
  for (const sub of subs) {
    let date = nextCharge(sub, today);
    while (daysBetween(today, date) <= within) {
      rows.push({ name: sub.name, date, when: shortLabel(date), inDays: daysBetween(today, date), price: sub.price, cycle: sub.cycle });
      if (sub.cycle === CYCLE.WEEK) {
        date = addDays(date, 7);
      } else if (sub.cycle === CYCLE.MONTH) {
        date = addMonths(date, 1);
      } else if (sub.cycle === CYCLE.YEAR) {
        date = addMonths(date, 12);
      }
    }
  }
  return rows.sort((a, b) => a.date.localeCompare(b.date) || a.name.localeCompare(b.name));
}

